/* DMS presentation over existing decimal calculation inputs. */
(()=>{'use strict';const mirrors=[];let queued=false;
function install(){for(const source of document.querySelectorAll('input[type="number"][id$="-latitude"],input[type="number"][id$="-longitude"]')){if(source.dataset.dmsInstalled)continue;source.dataset.dmsInstalled='true';source.classList.add('kp-coordinate-source');const longitude=source.id.endsWith('-longitude'),mirror=document.createElement('input');mirror.type='text';mirror.id=source.id+'-dms';mirror.className='kp-coordinate-dms';mirror.placeholder=longitude?'73:00:00 E':'18:00:00 N';mirror.setAttribute('aria-label',(longitude?'Longitude':'Latitude')+' · D:M:S');source.after(mirror);const label=document.querySelector('label[for="'+source.id+'"]');if(label)label.htmlFor=mirror.id;const refresh=()=>{if(document.activeElement!==mirror)mirror.value=source.value===''?'':KPClientPresentation.formatCoordinate(Number(source.value),longitude);};mirror.addEventListener('change',()=>{try{const n=KPDefaultLocation.coordinate(mirror.value,longitude);mirror.setCustomValidity('');source.value=String(n);source.dispatchEvent(new Event('input',{bubbles:true}));source.dispatchEvent(new Event('change',{bubbles:true}));refresh();}catch(e){mirror.setCustomValidity(e.message);mirror.reportValidity();}});source.addEventListener('input',refresh);source.addEventListener('change',refresh);mirror.addEventListener('focus',refresh);mirrors.push(refresh);refresh();}}
function refresh(){install();for(const f of mirrors)f();}
function init(){const css=document.createElement('style');css.textContent='@media screen{body.app-ready .kp-coordinate-source{display:none!important}body.app-ready .kp-coordinate-dms{display:block!important;box-sizing:border-box;max-width:100%}}';document.head.append(css);const old=KPClientPresentation.refreshCoordinates;KPClientPresentation.refreshCoordinates=()=>{old();refresh();};refresh();new MutationObserver(records=>{if(!queued&&records.some(r=>r.addedNodes.length)){queued=true;requestAnimationFrame(()=>{queued=false;refresh();});}}).observe(document.body,{childList:true,subtree:true});setInterval(()=>{for(const f of mirrors)f();},1000);}
window.KPCoordinateDMS=Object.freeze({refresh});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
